StompClientSubProtocolInitializer:
public class StompClientSubProtocolInitializer extends ChannelInitializer<SocketChannel> {

    private final Consumer<Channel> consumer;
    private final Integer maxContentLength;

    public StompClientSubProtocolInitializer(int maxContentLength, Consumer<Channel> consumer) {
        this.consumer = consumer;
        this.maxContentLength = maxContentLength;
    }

    @Override
    protected void initChannel(SocketChannel channel) throws Exception {
        channel.pipeline().addLast(new MessageToMessageCodec<WebSocketFrame, ByteBuf>() {
            @Override
            public void userEventTriggered(ChannelHandlerContext ctx, Object evt) throws Exception {
                if (evt instanceof WebSocketClientProtocolHandler.ClientHandshakeStateEvent && evt == WebSocketClientProtocolHandler.ClientHandshakeStateEvent.HANDSHAKE_COMPLETE) {
                    ctx.pipeline()
                            .addLast("decoder", new StompSubframeDecoder())
                            .addLast("encoder", new StompSubframeEncoder())
                            .addLast("aggregator", new StompSubframeAggregator(maxContentLength))
                            .addLast("handler", new StompClientHandler());
                    if (consumer != null) {
                        consumer.accept(ctx.channel());
                    }
                } else {
                    super.userEventTriggered(ctx, evt);
                }
            }

            @Override
            protected void encode(ChannelHandlerContext ctx, ByteBuf stompFrame, List<Object> out) {
                out.add(new TextWebSocketFrame(stompFrame.retain()));
            }

            @Override
            protected void decode(ChannelHandlerContext ctx, WebSocketFrame webSocketFrame, List<Object> out) {
                if (webSocketFrame instanceof TextWebSocketFrame) {
                    out.add(webSocketFrame.content().retain());
                } else {
                    ctx.close();
                }
            }

        });
    }
}
